"""Pytest-process audit counters; launch under sandbox-exec for OS network denial."""
from pathlib import Path
import json
import ipaddress
import os
import socket
import sys
import tempfile

ROOT = Path("/Users/nikolassapalidis/Developer/co-train")
sys.path.insert(0, str(ROOT))
os.chdir(ROOT)


def main():
    args = sys.argv[1:]
    probe = args.pop(0) if args and args[0].startswith("--probe-") else None
    counts = {"network_attempts": 0, "cache_file_accesses": 0, "tokenizer_loads": 0,
              "loopback_events": 0}
    with tempfile.TemporaryDirectory(prefix="co-train-cold-cache-") as directory:
        cache = Path(directory)
        paths = {
            "HF_HOME": cache / "hf",
            "HF_HUB_CACHE": cache / "hf" / "hub",
            "HUGGINGFACE_HUB_CACHE": cache / "hf" / "hub",
            "HF_DATASETS_CACHE": cache / "hf" / "datasets",
            "HF_MODULES_CACHE": cache / "hf" / "modules",
            "TRANSFORMERS_CACHE": cache / "transformers",
            "XDG_CACHE_HOME": cache / "xdg",
        }
        for name, path in paths.items():
            os.environ[name] = str(path)
        os.environ.update({
            "HF_HUB_OFFLINE": "1",
            "TRANSFORMERS_OFFLINE": "1",
            "HF_DATASETS_OFFLINE": "1",
            "PYTHONDONTWRITEBYTECODE": "1",
        })
        os.environ.pop("PYTEST_ADDOPTS", None)

        guard_active = True

        def loopback(value):
            if isinstance(value, tuple):
                value = value[0]
            if value == "localhost" or value == b"localhost":
                return True
            try:
                return ipaddress.ip_address(os.fsdecode(value)).is_loopback
            except (ValueError, TypeError):
                return False

        def audit(event, arguments):
            if not guard_active:
                return
            if event in {"socket.connect", "socket.getaddrinfo", "socket.gethostbyname",
                         "socket.gethostbyaddr", "socket.sendto"}:
                address = arguments[1] if event in {"socket.connect", "socket.sendto"} else arguments[0]
                if loopback(address):
                    counts["loopback_events"] += 1
                    return
                counts["network_attempts"] += 1
                raise PermissionError("OFFLINE_NETWORK_ATTEMPT")
            if event in {"open", "os.listdir", "os.scandir"} and arguments and isinstance(
                    arguments[0], (str, bytes, os.PathLike)):
                path = Path(os.fsdecode(arguments[0])).absolute()
                if path.is_relative_to(cache):
                    counts["cache_file_accesses"] += 1
                    raise PermissionError("OFFLINE_CACHE_FILE_ACCESS")

        original_stat = os.stat

        def guarded_stat(path, *args, **kwargs):
            if guard_active and isinstance(path, (str, bytes, os.PathLike)):
                candidate = Path(os.fsdecode(path)).absolute()
                if candidate.is_relative_to(cache):
                    counts["cache_file_accesses"] += 1
                    raise PermissionError("OFFLINE_CACHE_METADATA_ACCESS")
            return original_stat(path, *args, **kwargs)

        def profile(frame, event, argument):
            if (event == "call" and frame.f_code.co_name == "from_pretrained"
                    and "tokenization" in frame.f_globals.get("__name__", "")
                    and frame.f_globals.get("__name__", "").startswith("transformers")):
                counts["tokenizer_loads"] += 1
                raise RuntimeError("OFFLINE_TOKENIZER_LOAD")

        sys.addaudithook(audit)
        os.stat = guarded_stat
        sys.setprofile(profile)
        code = 0
        try:
            if probe == "--probe-network":
                with socket.socket() as connection:
                    connection.connect(("192.0.2.1", 9))
            elif probe == "--probe-cache":
                (cache / "missing-tokenizer.json").read_bytes()
            elif probe == "--probe-cache-stat":
                (cache / "missing-tokenizer.json").exists()
            elif probe == "--probe-cache-list":
                os.listdir(cache)
            elif probe == "--probe-tokenizer":
                namespace = {"__name__": "transformers.tokenization_fixture"}
                exec("def from_pretrained():\n    return 'unreachable'\n", namespace)
                namespace["from_pretrained"]()
            elif probe is not None:
                raise ValueError("Unknown probe")
            else:
                import pytest
                code = int(pytest.main(["-p", "no:cacheprovider", *args]))
        except (PermissionError, RuntimeError) as error:
            print(type(error).__name__ + ": " + str(error), flush=True)
            code = 1
        finally:
            sys.setprofile(None)
            os.stat = original_stat
            print("OFFLINE_AUDIT " + json.dumps(counts, sort_keys=True), flush=True)
            guard_active = False
        return code or int(any(value for key, value in counts.items() if key != "loopback_events"))


if __name__ == "__main__":
    raise SystemExit(main())

