/* Real SDK libproc observer for the two test-fixture ps argument forms. */
#include <errno.h>
#include <limits.h>
#include <libproc.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    const char *text = NULL;
    if (argc == 5 && !strcmp(argv[1], "-p") &&
            !strcmp(argv[3], "-o") && !strcmp(argv[4], "stat=")) {
        text = argv[2];
    } else if (argc == 5 && !strcmp(argv[1], "-o") &&
            !strcmp(argv[2], "stat=") && !strcmp(argv[3], "-p")) {
        text = argv[4];
    }
    char *end = NULL;
    long pid = text ? strtol(text, &end, 10) : 0;
    int invalid = !text || !end || *end || pid <= 0 || pid > INT_MAX;
    struct proc_bsdinfo info = {0};
    errno = 0;
    int count = invalid ? 0 : proc_pidinfo((int)pid, PROC_PIDTBSDINFO, 0,
                                          &info, sizeof(info));
    int error = errno;
#ifdef FORCE_OBSERVER_ERROR
    count = 0;
    error = EPERM;
#endif
    int absent = !invalid && count == 0 && error == ESRCH;
    int valid = !invalid && count == sizeof(info) &&
        info.pbi_pid == pid && info.pbi_status >= 1 && info.pbi_status <= 5;
    int unknown = !absent && !valid;
    FILE *log = fopen(
        "/Users/nikolassapalidis/scratch/co-train-offline-reliability-2026-10-23/"
#ifdef FORCE_OBSERVER_ERROR
        "observer-error-observations.jsonl", "a");
#else
        "observer-native-observations.jsonl", "a");
#endif
    if (!log) {
        puts("UNKNOWN");
        return 0;
    }
    fprintf(log, "{\"pid\":%ld,\"bytes\":%d,\"errno\":%d,\"state\":%u,"
                 "\"observer_error\":%s}\n",
            pid, count, error, info.pbi_status, unknown ? "true" : "false");
    if (fclose(log)) unknown = 1;
    if (unknown) {
        puts("UNKNOWN"); /* Conservative: both fixtures treat this as executing. */
        return 0;
    }
    if (absent) return 1; /* Darwin excludes both zombies and absent PIDs. */
    const char states[] = "?IRSTZ";
    printf("%c\n", states[info.pbi_status]);
    return 0;
}
